/// @file test_input_sdl.cpp
/// @brief SDL → InputManager translation at the platform boundary (testing.md
/// §2.16). The state machine itself is covered SDL-free in test_input.cpp; this
/// TU proves the *wiring*: that a real SDL_Event reaches the right action.
///
/// Gamepad cases use SDL's own virtual-controller facility
/// (`SDL_AttachVirtualJoystick`) with `SDL_SetJoystickVirtualButton`/`Axis`, so
/// the events under test are generated by SDL's event pipeline rather than
/// hand-built — the same code path a USB controller drives, without needing a
/// controller (or a display) on the CI host. Deliberate SDL interop boundary in
/// the test layer (cpp.md §9.1).
#include "lod/diagnostics.h"
#include "lod/input.h"
#include "lod/log.h"
#include "lod/platform.h"
#include "sc_test.h"

#include <SDL3/SDL.h>

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <string>
#include <thread>
#include <vector>

namespace
{

std::string TempDir(const std::string& tag)
{
  const auto dir = std::filesystem::temp_directory_path() / ("lodsc-input-sdl-" + tag);
  std::error_code ec;
  std::filesystem::remove_all(dir, ec);
  return dir.string();
}

/// @brief Headless platform + the AppContext services a platform needs, torn
/// down in the right order (platform first, then its crash dir).
class InputFixture
{
public:
  explicit InputFixture(const std::string& tag) : diag_(TempDir(tag)), Ctx{log_, diag_, "headless"}
  {
    log_.SetMinLevel(lod::Level::Error); // keep test output clean
    Ready = Platform.Initialize(Ctx).has_value();
  }

  InputFixture(const InputFixture&) = delete;
  InputFixture& operator=(const InputFixture&) = delete;

  ~InputFixture() { Platform.Shutdown(); }

  [[nodiscard]] bool GamepadBackend() const { return SDL_WasInit(SDL_INIT_GAMEPAD) != 0; }

  [[nodiscard]] lod::InputManager& Input() { return Platform.Input(); }

  /// @brief One frame: drain the queue into the input state and return the
  /// window-level events (which these cases do not care about).
  void Frame() { (void)Platform.PollFrame(); }

  /// @brief Wait for SDL's joystick worker to publish injected virtual input.
  /// The virtual-controller state is flushed on an event-loop iteration of its
  /// own, so a poll that happens immediately may legitimately see nothing.
  static void Settle() { std::this_thread::sleep_for(std::chrono::milliseconds(60)); }

  bool Ready = false; ///< Initialize succeeded (checked by every case).

private:
  lod::Logger log_;
  lod::Diagnostics diag_;

public:
  lod::AppContext Ctx; ///< Declared after its members: it references them.
  lod::Platform Platform{[]
                         {
                           lod::Platform::Options options;
                           options.Headless = true;
                           options.Width = 320;
                           options.Height = 240;
                           options.Title = "lodsc input test";
                           return options;
                         }()};
};

/// @brief Binding under test: kind + platform code + action, with the usual
/// no-modifier / no-direction defaults.
[[nodiscard]] lod::InputBinding Bind(lod::BindingKind kind, std::uint32_t code, std::string action,
                                     lod::AxisDirection direction = lod::AxisDirection::None)
{
  lod::InputBinding binding;
  binding.Kind = kind;
  binding.Code = code;
  binding.ActionID = std::move(action);
  binding.Direction = direction;
  return binding;
}

/// @brief The controls every case below shares: Enter or pad-A confirms, the
/// stick's +X drives "move.right", and Escape is a keyboard-only action (used
/// where keyboard suppression has to be observable).
void BindSampleControls(lod::InputManager& input)
{
  input.RegisterAction("confirm", false);
  input.RegisterAction("move.right", true);
  input.RegisterAction("menu.up", false);
  input.SetBindings({
    Bind(lod::BindingKind::Key, static_cast<std::uint32_t>(SDLK_RETURN), "confirm"),
    Bind(lod::BindingKind::Button, static_cast<std::uint32_t>(SDL_GAMEPAD_BUTTON_SOUTH), "confirm"),
    Bind(lod::BindingKind::Key, static_cast<std::uint32_t>(SDLK_ESCAPE), "menu.up"),
    Bind(lod::BindingKind::Axis, static_cast<std::uint32_t>(SDL_GAMEPAD_AXIS_LEFTX), "move.right",
         lod::AxisDirection::Positive),
  });
}

/// @brief Push one keyboard event the way SDL delivers it (the `key` member
/// alias is what SDL reads, so the struct is filled through it).
void PushKey(bool down, SDL_Keycode key, SDL_Scancode scan)
{
  SDL_Event event{};
  event.key.type = down ? SDL_EVENT_KEY_DOWN : SDL_EVENT_KEY_UP;
  event.key.timestamp = SDL_GetTicksNS();
  event.key.key = key;
  event.key.scancode = scan;
  event.key.mod = SDL_KMOD_NONE;
  event.key.down = down;
  event.key.repeat = false;
  (void)SDL_PushEvent(&event);
}

/// @brief An attached virtual gamepad, detached at scope end (SDL keeps
/// attached devices alive across SDL_QuitSubSystem, so leaving one behind would
/// leak into the next case).
class VirtualPad
{
public:
  VirtualPad()
  {
    SDL_VirtualJoystickDesc desc;
    SDL_INIT_INTERFACE(&desc);
    desc.type = SDL_JOYSTICK_TYPE_GAMEPAD;
    desc.naxes = static_cast<std::uint16_t>(SDL_GAMEPAD_AXIS_COUNT);
    desc.nbuttons = static_cast<std::uint16_t>(SDL_GAMEPAD_BUTTON_COUNT);
    desc.button_mask = (1u << SDL_GAMEPAD_BUTTON_COUNT) - 1u;
    desc.axis_mask = (1u << SDL_GAMEPAD_AXIS_COUNT) - 1u;
    id = SDL_AttachVirtualJoystick(&desc);
  }

  VirtualPad(const VirtualPad&) = delete;
  VirtualPad& operator=(const VirtualPad&) = delete;

  ~VirtualPad()
  {
    if (id != 0)
      (void)SDL_DetachVirtualJoystick(id);
  }

  [[nodiscard]] bool Attached() const { return id > 0; }
  [[nodiscard]] std::uint32_t ID32() const { return static_cast<std::uint32_t>(id); }

  /// @brief The joystick handle SDL created for this pad (null until the pad
  /// has been opened — which is exactly what the platform layer is tested to
  /// do).
  [[nodiscard]] SDL_Joystick* Handle() const { return SDL_GetJoystickFromID(id); }

  SDL_JoystickID id = 0;
};

} // namespace

/// @brief Skip (not fail) a gamepad case on a host with no controller backend:
/// there is no device to attach, and a red suite that tests nothing is worse
/// than a visible skip. The state machine behind these cases is covered
/// SDL-free in test_input.cpp, so the logic never goes untested.
#define SKIP_WITHOUT_GAMEPAD(fixture)                                                                                  \
  if (!(fixture).GamepadBackend())                                                                                     \
  {                                                                                                                    \
    std::printf("    (no gamepad backend on this host — skipped)\n");                                                  \
    return;                                                                                                            \
  }

/// @brief Skip a case on a host whose controller backend cannot provide a
/// *virtual* device. Attaching one is a backend capability (HID access), not a
/// project feature: a runner without it must not go red, and it must not
/// silently pretend to have tested the controller path either.
#define SKIP_WITHOUT_VIRTUAL_PAD(pad)                                                                                  \
  if (!(pad).Attached())                                                                                               \
  {                                                                                                                    \
    std::printf("    (no virtual controller available on this host — skipped)\n");                                     \
    return;                                                                                                            \
  }

LOD_TEST(input, sdl_keyboard_action_round_trip)
{
  InputFixture fixture("sdl-key");
  LOD_REQUIRE(fixture.Ready);
  BindSampleControls(fixture.Input());
  fixture.Frame(); // drain whatever window creation queued

  LOD_CHECK(!fixture.Input().ActionPressed("confirm"));

  PushKey(true, SDLK_RETURN, SDL_SCANCODE_RETURN);
  fixture.Frame();
  LOD_CHECK(fixture.Input().ActionPressed("confirm"));
  LOD_CHECK(fixture.Input().ActionHeld("confirm"));
  LOD_CHECK(fixture.Input().LastInputClass() == lod::InputClass::Keyboard);

  // Held, but the press edge belongs to the previous frame only.
  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionPressed("confirm"));
  LOD_CHECK(fixture.Input().ActionHeld("confirm"));

  PushKey(false, SDLK_RETURN, SDL_SCANCODE_RETURN);
  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionHeld("confirm"));
}

LOD_TEST(input, sdl_auto_repeat_is_not_a_fresh_press)
{
  InputFixture fixture("sdl-repeat");
  LOD_REQUIRE(fixture.Ready);
  BindSampleControls(fixture.Input());
  fixture.Frame();

  PushKey(true, SDLK_RETURN, SDL_SCANCODE_RETURN);
  fixture.Frame();
  LOD_CHECK(fixture.Input().ActionPressed("confirm"));

  // An OS auto-repeat carries repeat=true; it must not re-arm the press edge.
  SDL_Event repeat{};
  repeat.key.type = SDL_EVENT_KEY_DOWN;
  repeat.key.timestamp = SDL_GetTicksNS();
  repeat.key.key = SDLK_RETURN;
  repeat.key.scancode = SDL_SCANCODE_RETURN;
  repeat.key.down = true;
  repeat.key.repeat = true;
  (void)SDL_PushEvent(&repeat);

  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionPressed("confirm"));
  LOD_CHECK(fixture.Input().ActionHeld("confirm"));
}

LOD_TEST(input, sdl_opens_a_connected_gamepad)
{
  InputFixture fixture("sdl-open");
  LOD_REQUIRE(fixture.Ready);
  SKIP_WITHOUT_GAMEPAD(fixture);
  BindSampleControls(fixture.Input());
  fixture.Frame();

  VirtualPad pad;
  SKIP_WITHOUT_VIRTUAL_PAD(pad);

  // SDL queues the device-added events itself; the platform must open the pad
  // (SDL delivers no button/axis events for an unopened one) and register it.
  fixture.Settle();
  fixture.Frame();
  LOD_CHECK(fixture.Input().GamepadCount() == 1);
  LOD_REQUIRE(pad.Handle() != nullptr); // opened by the platform, not the test

  fixture.Frame();
  LOD_CHECK(fixture.Input().GamepadCount() == 1); // idempotent, not re-added
}

LOD_TEST(input, sdl_gamepad_button_and_axis_drive_actions)
{
  InputFixture fixture("sdl-pad-input");
  LOD_REQUIRE(fixture.Ready);
  SKIP_WITHOUT_GAMEPAD(fixture);
  BindSampleControls(fixture.Input());
  fixture.Frame();

  VirtualPad pad;
  SKIP_WITHOUT_VIRTUAL_PAD(pad);
  fixture.Settle();
  fixture.Frame(); // opens the pad
  SDL_Joystick* handle = pad.Handle();
  LOD_REQUIRE(handle != nullptr);

  LOD_CHECK(!fixture.Input().ActionHeld("confirm"));
  LOD_REQUIRE(SDL_SetJoystickVirtualButton(handle, SDL_GAMEPAD_BUTTON_SOUTH, true));
  fixture.Settle();
  fixture.Frame();
  LOD_CHECK(fixture.Input().ActionPressed("confirm"));
  LOD_CHECK(fixture.Input().GamepadInputHeld());
  LOD_CHECK(fixture.Input().LastInputClass() == lod::InputClass::Gamepad);
  LOD_CHECK(fixture.Input().LastGamepadID() == static_cast<int>(pad.ID32()));

  // The stick's +X beyond the movement outer edge reads as full deflection.
  LOD_REQUIRE(SDL_SetJoystickVirtualButton(handle, SDL_GAMEPAD_BUTTON_SOUTH, false));
  LOD_REQUIRE(SDL_SetJoystickVirtualAxis(handle, SDL_GAMEPAD_AXIS_LEFTX, 30000));
  fixture.Settle();
  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionHeld("confirm"));
  LOD_CHECK(fixture.Input().ActionHeld("move.right"));
  LOD_CHECK(fixture.Input().ActionAxis("move.right") > 0.99f);
  LOD_CHECK(fixture.Input().ActionAxis("move.right") <= 1.0f);

  // Centering the stick releases the action (a yanked or centred axis must
  // never leave a movement action stuck).
  LOD_REQUIRE(SDL_SetJoystickVirtualAxis(handle, SDL_GAMEPAD_AXIS_LEFTX, 0));
  fixture.Settle();
  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionHeld("move.right"));
  LOD_CHECK(!fixture.Input().GamepadInputHeld());
}

LOD_TEST(input, sdl_unopened_pad_cannot_drive_input)
{
  InputFixture fixture("sdl-phantom");
  LOD_REQUIRE(fixture.Ready);
  SKIP_WITHOUT_GAMEPAD(fixture);
  BindSampleControls(fixture.Input());
  fixture.Frame();

  SDL_Event axis{};
  axis.gaxis.type = SDL_EVENT_GAMEPAD_AXIS_MOTION;
  axis.gaxis.timestamp = SDL_GetTicksNS();
  axis.gaxis.which = 4242; // no such pad: never attached, never opened
  axis.gaxis.axis = SDL_GAMEPAD_AXIS_LEFTX;
  axis.gaxis.value = 30000;
  (void)SDL_PushEvent(&axis);

  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionHeld("move.right"));
  LOD_CHECK(!fixture.Input().GamepadInputHeld());
  LOD_CHECK(fixture.Input().GamepadCount() == 0);
}

LOD_TEST(input, sdl_steam_guard_suppresses_keyboard_while_pad_held)
{
  InputFixture fixture("sdl-guard");
  LOD_REQUIRE(fixture.Ready);
  SKIP_WITHOUT_GAMEPAD(fixture);
  BindSampleControls(fixture.Input());
  fixture.Frame();

  VirtualPad pad;
  SKIP_WITHOUT_VIRTUAL_PAD(pad);
  fixture.Settle();
  fixture.Frame();
  SDL_Joystick* handle = pad.Handle();
  LOD_REQUIRE(handle != nullptr);

  LOD_REQUIRE(SDL_SetJoystickVirtualButton(handle, SDL_GAMEPAD_BUTTON_SOUTH, true));
  fixture.Settle();
  fixture.Frame();
  LOD_REQUIRE(fixture.Input().GamepadInputHeld());

  // Steam Input's synthetic key event arrives while the controller is held:
  // the guard must drop it, and Escape is keyboard-only so the drop is visible.
  PushKey(true, SDLK_ESCAPE, SDL_SCANCODE_ESCAPE);
  fixture.Frame();
  LOD_CHECK(!fixture.Input().ActionPressed("menu.up"));
  LOD_CHECK(!fixture.Input().ActionHeld("menu.up"));
  LOD_CHECK(fixture.Input().KeyboardSuppressed());
}

LOD_TEST(input, sdl_unplugging_a_pad_releases_its_state)
{
  InputFixture fixture("sdl-unplug");
  LOD_REQUIRE(fixture.Ready);
  SKIP_WITHOUT_GAMEPAD(fixture);
  BindSampleControls(fixture.Input());
  fixture.Frame();

  {
    VirtualPad pad;
    SKIP_WITHOUT_VIRTUAL_PAD(pad);
    fixture.Settle();
    fixture.Frame();
    SDL_Joystick* handle = pad.Handle();
    LOD_REQUIRE(handle != nullptr);

    LOD_REQUIRE(SDL_SetJoystickVirtualAxis(handle, SDL_GAMEPAD_AXIS_LEFTX, 30000));
    fixture.Settle();
    fixture.Frame();
    LOD_REQUIRE(fixture.Input().ActionHeld("move.right"));

    // Detaching posts the removed event; the next frame must see the pad go
    // away *and* release the axis it was holding. Test-only detach: the real
    // event comes from the OS.
    (void)SDL_DetachVirtualJoystick(pad.ID32());
    fixture.Settle();
    fixture.Frame();
    LOD_CHECK(fixture.Input().GamepadCount() == 0);
    LOD_CHECK(!fixture.Input().ActionHeld("move.right"));
    LOD_CHECK(!fixture.Input().GamepadInputHeld());
  }
}

LOD_TEST(input, sdl_shutdown_releases_controllers)
{
  InputFixture fixture("sdl-shutdown");
  LOD_REQUIRE(fixture.Ready);
  SKIP_WITHOUT_GAMEPAD(fixture);
  fixture.Frame();

  VirtualPad pad;
  SKIP_WITHOUT_VIRTUAL_PAD(pad);
  fixture.Settle();
  fixture.Frame();
  LOD_REQUIRE(fixture.Input().GamepadCount() == 1);

  fixture.Input().RegisterAction("confirm", false);
  fixture.Input().SetBindings(
    {Bind(lod::BindingKind::Button, static_cast<std::uint32_t>(SDL_GAMEPAD_BUTTON_SOUTH), "confirm")});
  fixture.Frame();
  fixture.Platform.Shutdown();

  // No pad handle may outlive the platform: SDLGamepadDeleter closes them.
  LOD_CHECK(pad.Handle() == nullptr);
  LOD_CHECK(fixture.Input().GamepadCount() == 0);
  LOD_CHECK(!fixture.Input().ActionHeld("confirm"));
  LOD_CHECK(SDL_WasInit(SDL_INIT_GAMEPAD) == 0);
}
